function walkBothWays(head) {
  const forward = [];
  let curr = head, tail = null;
  while (curr !== null) {          // forward: follow next until null
    forward.push(curr.val);
    tail = curr;                   // remember the last node we saw
    curr = curr.next;
  }
  const backward = [];
  curr = tail;
  while (curr !== null) {          // backward: follow prev from the tail
    backward.push(curr.val);
    curr = curr.prev;
  }
  return [forward, backward];
}

List<List<Integer>> walkBothWays(Node head) {
    List<Integer> forward = new ArrayList<>();
    Node curr = head, tail = null;
    while (curr != null) {          // forward: follow next until null
        forward.add(curr.val);
        tail = curr;                // remember the last node we saw
        curr = curr.next;
    }
    List<Integer> backward = new ArrayList<>();
    curr = tail;
    while (curr != null) {          // backward: follow prev from the tail
        backward.add(curr.val);
        curr = curr.prev;
    }
    return List.of(forward, backward);
}

vector<vector<int>> walkBothWays(Node* head) {
    vector<int> forward, backward;
    Node* curr = head;
    Node* tail = nullptr;
    while (curr != nullptr) {       // forward: follow next until null
        forward.push_back(curr->val);
        tail = curr;                // remember the last node we saw
        curr = curr->next;
    }
    curr = tail;
    while (curr != nullptr) {       // backward: follow prev from the tail
        backward.push_back(curr->val);
        curr = curr->prev;
    }
    return {forward, backward};
}

function walkCircular(head) {
  const values = [];
  if (head === null) return values;   // an empty ring has nothing to visit
  let curr = head;
  do {
    values.push(curr.val);
    curr = curr.next;
  } while (curr !== head);            // stop when we're back at the start
  return values;
}

List<Integer> walkCircular(ListNode head) {
    List<Integer> values = new ArrayList<>();
    if (head == null) return values;     // an empty ring has nothing to visit
    ListNode curr = head;
    do {
        values.add(curr.val);
        curr = curr.next;
    } while (curr != head);              // stop when we're back at the start
    return values;
}

vector<int> walkCircular(ListNode* head) {
    vector<int> values;
    if (head == nullptr) return values;  // an empty ring has nothing to visit
    ListNode* curr = head;
    do {
        values.push_back(curr->val);
        curr = curr->next;
    } while (curr != head);              // stop when we're back at the start
    return values;
}
